import json,platform,sys; from importlib import metadata; result={'python':sys.version,'executable':sys.executable,'platform':platform.platform(),'packages':{}}
for name in ('numpy','pillow'):
 try: result['packages'][name]=metadata.version(name)
 except metadata.PackageNotFoundError: result['packages'][name]=None
try:
 from pxr import Usd
 result['usd_version']=list(Usd.GetVersion())
except ImportError: result['usd_version']=None
print(json.dumps(result))

